{"category_edits":[{"category":"learning_objective","rationale":"Add a 0.05-weighted pairwise margin loss over existing valid positions and sampled negatives to encourage better positive-negative separation across all four datasets, preserving the existing objective and training configuration.","edits":[{"find":"    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)
    return (weights * pairwise_loss).sum()","replace":"    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)
    margin_loss = torch.relu(1.0 + valid_neg - valid_pos).mean()
    return (weights * pairwise_loss).sum() + 0.05 * margin_loss"}]}],"change_summary":"Augment the existing loss with a masked pairwise hinge term. Sampling, GRU architecture, inference, routing, and training settings remain unchanged."}
